import java.io.*;
import java.util.StringTokenizer;

/**
 * Code with different variable naming and inline comments.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int totalPoints = Integer.parseInt(st.nextToken());
        int threshold = Integer.parseInt(st.nextToken());
        int lengthMultiplier = Integer.parseInt(st.nextToken());

        int MOD = 998244353;
        long[] invs = IntegerUtils.invs(2 * totalPoints + 3, MOD);
        long[][] dpStates = new long[2 * totalPoints + 1][totalPoints + 1];
        // Initialize starting state
        dpStates[0][1] = 1;

        for (int step = 1; step < 2 * totalPoints; step++) {
            int maxPrevIntervals = Math.min(2 * totalPoints - step, step);
            int maxNewIntervals = Math.min(2 * totalPoints - step - 1, step + 1);
            for (int active = 0; active <= maxPrevIntervals; active++) {
                if (dpStates[step - 1][active] != 0) {
                    if (active > 0) {
                        // Close an interval
                        dpStates[step][active - 1] = (dpStates[step][active - 1] + dpStates[step - 1][active] * active % MOD * invs[2 * totalPoints - step]) % MOD;
                    }
                    if (active < maxNewIntervals) {
                        // Start a new interval
                        dpStates[step][active + 1] = (dpStates[step][active + 1] + dpStates[step - 1][active] * (2 * totalPoints - step - active) % MOD * invs[2 * totalPoints - step]) % MOD;
                    }
                }
            }
        }

        long result = 0;
        for (int i = 0; i < 2 * totalPoints; i++) {
            for (int j = threshold; j <= totalPoints; j++) {
                result = (result + dpStates[i][j]) % MOD;
            }
        }
        result = result * lengthMultiplier % MOD * invs[2 * totalPoints + 1] % MOD;
        pw.println(result);
        pw.close();
    }

    static class IntegerUtils {
        public static long[] invs(int n, long p) {
            long[] res = new long[n];
            res[1] = 1;
            for (int i = 2; i < n; i++) {
                res[i] = (p - (p / i) * res[(int) (p % i)] % p) % p;
            }
            return res;
        }
    }
}
